func TestEnumCompatibleEndpoint(t *testing.T) {
	t.Run("NewFromString_chat", func(t *testing.T) {
		t.Parallel()
		val, err := NewCompatibleEndpointFromString("chat")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, CompatibleEndpoint("chat"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_embed", func(t *testing.T) {
		t.Parallel()
		val, err := NewCompatibleEndpointFromString("embed")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, CompatibleEndpoint("embed"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_classify", func(t *testing.T) {
		t.Parallel()
		val, err := NewCompatibleEndpointFromString("classify")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, CompatibleEndpoint("classify"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_summarize", func(t *testing.T) {
		t.Parallel()
		val, err := NewCompatibleEndpointFromString("summarize")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, CompatibleEndpoint("summarize"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_rerank", func(t *testing.T) {
		t.Parallel()
		val, err := NewCompatibleEndpointFromString("rerank")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, CompatibleEndpoint("rerank"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_rate", func(t *testing.T) {
		t.Parallel()
		val, err := NewCompatibleEndpointFromString("rate")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, CompatibleEndpoint("rate"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_generate", func(t *testing.T) {
		t.Parallel()
		val, err := NewCompatibleEndpointFromString("generate")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, CompatibleEndpoint("generate"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_Invalid", func(t *testing.T) {
		_, err := NewCompatibleEndpointFromString("invalid_value_that_does_not_exist")
		assert.Error(t, err)
	})

	t.Run("Ptr", func(t *testing.T) {
		val, err := NewCompatibleEndpointFromString("chat")
		assert.NoError(t, err)
		ptr := val.Ptr()
		assert.NotNil(t, ptr)
		assert.Equal(t, val, *ptr)
	})
}

func TestExtraPropertiesGetModelResponse(t *testing.T) {
	t.Run("GetExtraProperties", func(t *testing.T) {
		t.Parallel()
		obj := &GetModelResponse{}
		// Should not panic when calling GetExtraProperties()
		defer func() {
			if r := recover(); r != nil {
				t.Errorf("GetExtraProperties() panicked: %v", r)
			}
		}()
		extraProps := obj.GetExtraProperties()
		// Result can be nil or an empty/non-empty map
		_ = extraProps
	})

	t.Run("GetExtraProperties_NilReceiver", func(t *testing.T) {
		t.Parallel()
		var obj *GetModelResponse
		extraProps := obj.GetExtraProperties()
		assert.Nil(t, extraProps, "nil receiver should return nil without panicking")
	})
}

